diff.website/css/sales.css:
--- a/website/css/sales.css
+++ b/website/css/sales.css
@@ -1,2 +1,2 @@
-/* Jago Prompt 1.3.0 — perubahan konten, bukan penggantian design system. */
+/* Jago Prompt 1.3.0–1.4.0 — perubahan konten, bukan penggantian design system. */
 .sales-support { font-size: var(--fs-small); color: var(--ink-2); line-height: 1.65; margin-top: 12px; max-width: 48ch; }
@@ -102 +102,14 @@
 .sales-page h1, .sales-page h2, .sales-page h3 { overflow-wrap: anywhere; }
+/* 1.4.0 — teks narasi video (alternatif caption; tetap terbaca tanpa JS) */
+.media-transcript { border-top: 1px solid var(--line); }
+.media-transcript > summary { font-size: 14px; padding: 12px 2px; }
+.media-transcript > p { font-size: 14px; line-height: 1.6; color: var(--ink-2); padding: 0 2px 12px; }
+/* 1.4.0 — font cadangan bermetrik selaras: saat Plus Jakarta Sans belum selesai dimuat, teks cadangan menempati
+   lebar dan tinggi yang hampir sama, sehingga judul hero tidak berpindah baris (CLS desktop 0,14 pada 1.3.0).
+   Plus Jakarta Sans tetap font utama; tampilan akhir tidak berubah. Rasio dihitung dari metrik berkas font.
+   unicode-range membatasi cadangan ini pada huruf Latin dasar, sehingga simbol (·, →, ©) tetap memakai font sistem seperti sebelumnya. */
+@font-face { font-family: "JP Fallback"; font-weight: 100 600; src: local("Arial"), local("Liberation Sans"), local("Helvetica Neue"), local("Roboto"); size-adjust: 104.8%; ascent-override: 99%; descent-override: 21.2%; line-gap-override: 0%; unicode-range: U+0020-007E; }
+@font-face { font-family: "JP Fallback"; font-weight: 601 900; src: local("Arial Bold"), local("Liberation Sans Bold"), local("Helvetica Neue Bold"), local("Roboto Bold"); size-adjust: 101%; ascent-override: 102.8%; descent-override: 22%; line-gap-override: 0%; unicode-range: U+0020-007E; }
+:root { --font: "Plus Jakarta Sans", "JP Fallback", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; }
+/* 1.4.0 — target sentuh tautan footer minimal 44px (sebelumnya 40px) */
+.sales-page .footer-nav a { display: inline-flex; align-items: center; min-height: 44px; }

